intpcntl_rfork intflags intsignal0
Функция управляет ресурсами процесса.

  &reftitle.examples;



    Пример управления ресурсами процесса функцией pcntl_rfork


<?php

$pid = pcntl_rfork(RFNOWAIT | RFTSIGZMB, SIGUSR1);

if ($pid > 0) {
    // Родительский процесс
    var_dump($pid);
} else {
    // Для дочернего процесса переменной $pid присваивается значение 0
    var_dump($pid);
    sleep(2); // Удерживаем дочерний процесс активным, чтобы увидеть вывод
              // или PID потомка в списке процессов,
              // поскольку родитель не ждёт завершения потомка
}


    &example.outputs.similar;


